def _make_concat_multiindex(indexes, keys, levels=None, names=None) -> MultiIndex:
    # We need to ensure that keys are unique to avoid the TypeError
    # If keys are not unique, we append a unique identifier to the duplicate keys
    unique_keys = []
    key_counts = {}
    for key in keys:
        if key in key_counts:
            key_counts[key] += 1
            unique_keys.append(f"{key}_{key_counts[key]}")
        else:
            key_counts[key] = 0
            unique_keys.append(key)

    if (levels is None and isinstance(unique_keys[0], tuple)) or (
        levels is not None and len(levels) > 1
    ):
        zipped = list(zip(*unique_keys))
        if names is None:
            names = [None] * len(zipped)

        if levels is None:
            _, levels = factorize_from_iterables(zipped)
        else:
            levels = [ensure_index(x) for x in levels]
    else:
        zipped = [unique_keys]
        if names is None:
            names = [None]

        if levels is None:
            levels = [ensure_index(unique_keys)]
        else:
            levels = [ensure_index(x) for x in levels]

    if not all_indexes_same(indexes):
        codes_list = []

        # things are potentially different sizes, so compute the exact codes
        # for each level and pass those to MultiIndex.from_arrays

